node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Record the transfer in the database - check if there's a transfers or support table
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all().map(t => t.name);
console.log('Looking for relevant tables:', tables.filter(t => t.includes('support') || t.includes('transfer') || t.includes('ticket')));

// Update the booking to note the transfer request
const booking = db.prepare(\"SELECT * FROM flight_bookings WHERE booking_id = 'BK-B70889'\").get();
console.log('Current status:', booking.status);
"
